import { Component, OnInit, ViewChild, ElementRef, AfterViewInit, OnDestroy, HostListener, AfterViewChecked, ChangeDetectorRef } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { Chart, ChartConfiguration, registerables } from 'chart.js';
import { trigger, transition, style, animate, stagger, query } from '@angular/animations';
import { HelpSupportComponent } from './components/help-support/help-support.component';
import { Router, NavigationEnd } from '@angular/router';
import { filter } from 'rxjs/operators';
import { FooterComponent } from '../../layouts/footer/footer.component';
import { RouterModule } from '@angular/router';
import { MenuComponent } from '../../layouts/menu/menu.component';
import { HeaderComponent } from '../../layouts/header/header.component';
import { NotificationService } from '../../core/services/notification/notification.service';
import { AuthService } from '../../core/services/auth.service';
import { LoadingService } from './../../core/services/loading.service';
import { ModuleLoaderService } from './../../core/services/module-loader.service';
import { DenunciaService } from '../../services/denuncia.service';
import { CatalogoService, TipoConflicto, EstadoDenuncia } from '../../services/catalogo.service';
import { Denuncia } from '../../interfaces/denuncia.interface';
import { SessionTimeoutModalComponent } from '../../core/components/session-timeout/session-timeout-modal.component';
import { Observable } from 'rxjs';

Chart.register(...registerables);

@Component({
  selector: 'app-dashboard',
  templateUrl: './dashboard.component.html',
  styleUrls: ['./dashboard.component.less'],
  standalone: true,
  imports: [
    CommonModule,
    SessionTimeoutModalComponent,
    FormsModule,
    HelpSupportComponent,
    RouterModule,
    FooterComponent,
    MenuComponent,
    HeaderComponent
  ],
  animations: [
    trigger('slideDown', [
      transition(':enter', [
        style({ opacity: 0, transform: 'translateY(-20px)' }),
        animate('300ms cubic-bezier(0.4, 0, 0.2, 1)',
          style({ opacity: 1, transform: 'translateY(0)' }))
      ]),
      transition(':leave', [
        animate('200ms cubic-bezier(0.4, 0, 0.2, 1)',
          style({ opacity: 0, transform: 'translateY(-20px)' }))
      ])
    ]),
    trigger('fadeIn', [
      transition(':enter', [
        style({ opacity: 0 }),
        animate('400ms cubic-bezier(0.4, 0, 0.2, 1)',
          style({ opacity: 1 }))
      ])
    ]),
    trigger('slideInLeft', [
      transition(':enter', [
        style({ opacity: 0, transform: 'translateX(-30px)' }),
        animate('500ms cubic-bezier(0.4, 0, 0.2, 1)',
          style({ opacity: 1, transform: 'translateX(0)' }))
      ])
    ]),
    trigger('slideInRight', [
      transition(':enter', [
        style({ opacity: 0, transform: 'translateX(30px)' }),
        animate('500ms cubic-bezier(0.4, 0, 0.2, 1)',
          style({ opacity: 1, transform: 'translateX(0)' }))
      ])
    ]),
    trigger('staggerIn', [
      transition(':enter', [
        query('.metric-card', [
          style({ opacity: 0, transform: 'translateY(20px)' }),
          stagger(100, [
            animate(
              '400ms cubic-bezier(0.4, 0, 0.2, 1)',
              style({ opacity: 1, transform: 'translateY(0)' })
            )
          ])
        ], { optional: true })
      ])
    ])
  ]
})
export class DashboardComponent implements OnInit, AfterViewInit, OnDestroy, AfterViewChecked {
  private moduleName = 'Vista General Dashboard';
  private dataLoaded = false;
  private isMarkedReady = false;
  private viewCheckedCount = 0;
 public isLoading$: Observable<boolean>;


  constructor(
    private router: Router,
    private moduleLoader: ModuleLoaderService,
    private loadingService: LoadingService,
    private cdr:ChangeDetectorRef,
    private notificationService: NotificationService,
    private denunciaService: DenunciaService,
    private catalogoService: CatalogoService
  ) { this.isLoading$ = this.loadingService.loading$;}



  @ViewChild('violenceChart', { static: false }) chartCanvas!: ElementRef<HTMLCanvasElement>;
  private violenceChart: Chart | null = null;

  // Variables compartidas con componentes hijos
  isSidebarCollapsed = false;
  isDarkTheme = false;

  // Variables para el modal de ayuda
  showHelpSupport: boolean = false;
  isMinimized: boolean = false;
  isMaximized: boolean = false;
  minimizing: boolean = false;
  showMinimizeNotification: boolean = false;
  currentRoute: string = '';

  // Variables para dropdowns y modales
  isSearchOpen = false;
  isNotificationsOpen = false;
  isUserMenuOpen = false;

  // Búsqueda
  searchQuery: string = '';
  searchResults: any[] = [];

  // NOTIFICACIONES CONSERVADAS
  notifications = [
    {
      user: 'John Doe',
      action: 'Nuevo ticket agregado',
      time: '30 min',
      read: false,
      avatar: 'JD'
    },
    {
      user: 'Joseph William',
      action: 'Compra de nuevo tema y pago realizado',
      time: '45 min',
      read: true,
      avatar: 'JW'
    },
    {
      user: 'Sara Soudain',
      action: 'Sesión iniciada actualmente',
      time: '50 min',
      read: true,
      avatar: 'SS'
    }
  ];

  // Configuración de usuario CONSERVADA
  user = {
    name: 'Admin SGPAZ',
    email: 'admin@sgpaz.com',
    avatar: 'A'
  };

  // NUEVAS MÉTRICAS REALES DEL SISTEMA (sin eliminar las existentes)
  denunciaStats = {
    totalDenuncias: 0,
    denunciasActivas: 0,
    denunciasResueltas: 0,
    conciliacionesExitosas: 0,
     tasaResolucion: 0,  // 👈 NUEVO
  denunciasPorMes: [] as { mes: string; total: number }[],
  ultimasDenuncias: [] as Denuncia[]
  };

  // Catálogos para el dashboard
  tiposConflicto: TipoConflicto[] = [];
  estadosDenuncia: EstadoDenuncia[] = [];

  get unreadNotificationsCount(): number {
    return this.notifications.filter(n => !n.read).length;
  }

  ngOnInit(): void {
    this.cdr.detectChanges();
    this.applyTheme();
    this.setupKeyboardShortcuts();
    this.moduleLoader.registerComponentInstance(this.moduleName, this);
    this.loadModuleData();

    // Inicializar ruta actual
    this.currentRoute = this.router.url;

    // Escuchar cambios de ruta
    this.router.events
      .pipe(filter(event => event instanceof NavigationEnd))
      .subscribe((event: NavigationEnd) => {
        this.currentRoute = event.urlAfterRedirects;
      });

    // NUEVA CARGA DE DATOS REALES (sin eliminar funcionalidades existentes)
    this.cargarDatosReales();
    this.cdr.detectChanges();
  }

  // NUEVO MÉTODO PARA CARGAR DATOS REALES
  private cargarDatosReales(): void {
    // Cargar estadísticas de denuncias
    this.denunciaService.getEstadisticas().subscribe({
      next: (response) => {
        if (response.success) {
          this.denunciaStats = {
            totalDenuncias: response.data.total_denuncias || 0,
            denunciasActivas: response.data.denuncias_activas || 0,
            denunciasResueltas: response.data.denuncias_resueltas || 0,
            conciliacionesExitosas: response.data.conciliaciones_exitosas || 0,
            tasaResolucion: response.data.tasa_resolucion || 0,  // 👈 NUEVO
            denunciasPorMes: response.data.denuncias_por_mes || [],
            ultimasDenuncias: response.data.ultimas_denuncias || []
          };
          // Actualizar el gráfico con datos reales si existe
          this.updateChartWithRealData(response.data.denuncias_por_mes);
        }
      },
      error: (error) => console.error('Error cargando estadísticas:', error)
    });

    // Cargar catálogos para filtros
    this.catalogoService.getTiposConflicto().subscribe({
      next: (data) => this.tiposConflicto = data,
      error: (error) => console.error('Error cargando tipos de conflicto:', error)
    });

    this.catalogoService.getEstadosDenuncia().subscribe({
      next: (data) => this.estadosDenuncia = data,
      error: (error) => console.error('Error cargando estados de denuncia:', error)
    });
  }

  // NUEVO MÉTODO PARA ACTUALIZAR GRÁFICO CON DATOS REALES
  private updateChartWithRealData(datosPorMes: any[]): void {
    if (!this.violenceChart || !datosPorMes || datosPorMes.length === 0) return;

    const meses = datosPorMes.map(item => item.mes);
    const cantidades = datosPorMes.map(item => item.total);

    // Actualizar datos del gráfico existente
    if (this.violenceChart.data) {
      this.violenceChart.data.labels = meses;
      if (this.violenceChart.data.datasets[0]) {
        this.violenceChart.data.datasets[0].data = cantidades;
        this.violenceChart.data.datasets[0].label = 'Denuncias Registradas';
      }
      this.violenceChart.update();
    }
  }

  ngAfterViewChecked() {
    if (this.isMarkedReady) return;
    this.viewCheckedCount++;
    if (this.dataLoaded && this.viewCheckedCount >= 2) {
      console.log(`✅ Vista completamente estable (afterViewChecked x${this.viewCheckedCount})`);
      this.checkAndMarkReady();
    }
  }

  private async loadModuleData(): Promise<void> {
  try {
    console.log(`📡 Cargando datos para: ${this.moduleName}`);

    // ✅ Cargar datos específicos del dashboard
    await Promise.all([
      this.cargarDatosReales(),      // Cargar estadísticas
      this.initViolenceChart()      // Cargar indice de violencia
    ]);

    this.dataLoaded = true;
    console.log(`✅ Datos cargados para: ${this.moduleName}`);

    setTimeout(() => {
      this.checkAndMarkReady();
    }, 100);

  } catch (error) {
    console.error(`❌ Error cargando datos:`, error);
    this.markModuleAsReady();
  }
}

private checkAndMarkReady(): void {
  if (this.isMarkedReady) return;

  // ✅ Selectores específicos para el DASHBOARD (no para personal)
  const hasContent = document.querySelector('.dashboard-container, .main-content, app-dashboard');
  const hasData = document.querySelector('.metrics-container, .dashboard-grid, .chart-container');

  console.log(`🔍 [Dashboard] Verificando contenido: hasContent=${!!hasContent}, hasData=${!!hasData}`);

  if (this.dataLoaded && hasContent && hasData) {
    this.markModuleAsReady();
  } else if (this.dataLoaded) {
    setTimeout(() => this.checkAndMarkReady(), 200);
  }
}

  private markModuleAsReady(): void {
    if (this.isMarkedReady) return;
    this.isMarkedReady = true;
    console.log(`🏁 Marcando módulo como listo: ${this.moduleName}`);
    this.moduleLoader.markModuleRendered(this.moduleName);
  }

  private fetchData(url: string): Promise<any> {
    return new Promise(resolve => setTimeout(resolve, 500));
  }

  ngAfterViewInit(): void {
    setTimeout(() => {
      this.initViolenceChart();
    }, 200);
  }

  ngOnDestroy(): void {
    if (this.violenceChart) {
      this.violenceChart.destroy();
    }
    this.moduleLoader.markModuleRendered(this.moduleName);
    this.markModuleAsReady();
  }

  // MÉTODO DEL GRÁFICO ACTUALIZADO CON DATOS REALES (conservando estructura)
  private initViolenceChart(): void {
    if (!this.chartCanvas || !this.chartCanvas.nativeElement) {
      return;
    }

    const ctx = this.chartCanvas.nativeElement.getContext('2d');
    if (!ctx) return;

    // Configuración del gráfico con datos reales o de ejemplo
    const config: ChartConfiguration = {
      type: 'line',
      data: {
        labels: ['Ene', 'Feb', 'Mar', 'Abr', 'May', 'Jun'],
        datasets: [
          {
            label: 'Denuncias Registradas',
            data: [0, 0, 0, 0, 0, 0],
            borderColor: '#4f46e5',
            backgroundColor: 'rgba(79, 70, 229, 0.1)',
            borderWidth: 3,
            tension: 0.4,
            fill: true
          }
        ]
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        plugins: {
          legend: {
            display: false
          }
        },
        scales: {
          y: {
            beginAtZero: true,
            title: {
              display: true,
              text: 'Cantidad de Denuncias'
            },
            grid: {
              color: this.isDarkTheme ? 'rgba(255, 255, 255, 0.1)' : 'rgba(0, 0, 0, 0.1)'
            },
            ticks: {
              color: this.isDarkTheme ? '#f9fafb' : '#1f2937'
            }
          },
          x: {
            title: {
              display: true,
              text: 'Mes'
            },
            grid: {
              color: this.isDarkTheme ? 'rgba(255, 255, 255, 0.1)' : 'rgba(0, 0, 0, 0.1)'
            },
            ticks: {
              color: this.isDarkTheme ? '#f9fafb' : '#1f2937'
            }
          }
        }
      }
    };

    if (this.violenceChart) {
      this.violenceChart.destroy();
    }

    this.violenceChart = new Chart(ctx, config);
  }

  // ========== MÉTODOS PARA EL MENÚ (CONSERVADOS) ==========
  onToggleSidebar(): void {
    this.isSidebarCollapsed = !this.isSidebarCollapsed;
    if (this.isSidebarCollapsed) {
      document.body.classList.add('sidebar-collapsed');
    } else {
      document.body.classList.remove('sidebar-collapsed');
    }
  }

  onToggleHelpSupport(): void {
    this.showHelpSupport = !this.showHelpSupport;
    if (!this.showHelpSupport) {
      document.body.classList.remove('minimized-mode');
      this.isMinimized = false;
    }
  }

  // ========== MÉTODOS PARA EL HEADER (CONSERVADOS) ==========
  onToggleTheme(): void {
    this.isDarkTheme = !this.isDarkTheme;
    this.applyTheme();
    setTimeout(() => {
      this.updateChartTheme();
    }, 100);
  }

  onToggleNotifications(): void {
    this.isNotificationsOpen = !this.isNotificationsOpen;
    if (this.isNotificationsOpen) {
      this.isUserMenuOpen = false;
    }
  }

  onToggleUserMenu(): void {
    this.isUserMenuOpen = !this.isUserMenuOpen;
    if (this.isUserMenuOpen) {
      this.isNotificationsOpen = false;
    }
  }

  onMarkAllAsRead(): void {
    this.notifications.forEach(notification => notification.read = true);
  }

  onOpenSearchModal(): void {
    this.isSearchOpen = true;
    this.isNotificationsOpen = false;
    this.isUserMenuOpen = false;
  }

  // ========== MÉTODOS DEL MODAL DE AYUDA (CONSERVADOS) ==========
  handleOverlayClick(event: MouseEvent) {
    if ((event.target as HTMLElement).classList.contains('modal-overlay')) {
      if (this.showHelpSupport && !this.isMinimized) {
        this.minimizeToBubble();
      }
    }
  }

  minimizeToBubble() {
    this.isMinimized = true;
    this.minimizing = true;
    document.body.classList.add('minimized-mode');
    setTimeout(() => {
      this.minimizing = false;
      this.showMinimizeNotification = true;
      setTimeout(() => {
        this.showMinimizeNotification = false;
      }, 3000);
    }, 300);
  }

  restoreFromBubble() {
    this.isMinimized = false;
    document.body.classList.remove('minimized-mode');
  }

  closeBubble(event: MouseEvent) {
    event.stopPropagation();
    this.showHelpSupport = false;
    this.isMinimized = false;
    this.showMinimizeNotification = false;
  }

  toggleMinimize() {
    this.isMinimized = !this.isMinimized;
    if (this.isMinimized && this.isMaximized) {
      this.isMaximized = false;
    }
  }

  toggleMaximize() {
    this.isMaximized = !this.isMaximized;
    if (this.isMaximized && this.isMinimized) {
      this.isMinimized = false;
    }
  }

  closeModal(event: MouseEvent) {
    if ((event.target as HTMLElement).classList.contains('modal-overlay')) {
      this.onToggleHelpSupport();
    }
  }

  // ========== MÉTODOS DE BÚSQUEDA (CONSERVADOS) ==========
  closeSearchModal(): void {
    this.isSearchOpen = false;
    this.searchQuery = '';
    this.searchResults = [];
  }

  performSearch(): void {
    if (this.searchQuery.trim()) {
      this.searchResults = [
        {
          title: 'Documentación del Sistema',
          description: 'Manual completo del sistema SGPAZ',
          icon: '📚'
        },
        {
          title: 'Reportes Generados',
          description: 'Ver todos los reportes del mes',
          icon: '📈'
        },
        {
          title: 'Configuración de Usuarios',
          description: 'Gestión de permisos y accesos',
          icon: '👥'
        }
      ];
    }
  }

  clearSearch(): void {
    this.searchQuery = '';
    this.searchResults = [];
  }

  // ========== MÉTODOS PRIVADOS (CONSERVADOS) ==========
  private applyTheme(): void {
    if (this.isDarkTheme) {
      document.body.classList.add('dark-theme');
      document.body.classList.remove('light-theme');
    } else {
      document.body.classList.remove('dark-theme');
      document.body.classList.add('light-theme');
    }
  }

  private updateChartTheme(): void {
    if (this.violenceChart && this.violenceChart.options) {
      const textColor = this.isDarkTheme ? '#f9fafb' : '#1f2937';
      const gridColor = this.isDarkTheme ? 'rgba(255, 255, 255, 0.1)' : 'rgba(0, 0, 0, 0.1)';
      const options = this.violenceChart.options;
      if (options.scales) {
        const yAxis = options.scales['y'] as any;
        const xAxis = options.scales['x'] as any;
        if (yAxis) {
          if (yAxis.grid) yAxis.grid.color = gridColor;
          if (yAxis.ticks) yAxis.ticks.color = textColor;
        }
        if (xAxis) {
          if (xAxis.grid) xAxis.grid.color = gridColor;
          if (xAxis.ticks) xAxis.ticks.color = textColor;
        }
      }
      this.violenceChart.update();
    }
  }

  private setupKeyboardShortcuts(): void {
    document.addEventListener('keydown', (event) => {
      if ((event.ctrlKey || event.metaKey) && event.key === 'k') {
        event.preventDefault();
        this.onOpenSearchModal();
      }
      if (event.key === 'Escape') {
        if (this.isSearchOpen) {
          this.closeSearchModal();
        }
        if (this.isNotificationsOpen) {
          this.isNotificationsOpen = false;
        }
        if (this.isUserMenuOpen) {
          this.isUserMenuOpen = false;
        }
        if (this.showHelpSupport && !this.isMinimized) {
          this.minimizeToBubble();
        }
      }
    });
  }

  @HostListener('document:click', ['$event'])
  onClickOutside(event: MouseEvent): void {
    const target = event.target as HTMLElement;
    if (!target.closest('.notification-wrapper') && !target.closest('.notifications-dropdown')) {
      this.isNotificationsOpen = false;
    }
    if (!target.closest('.user-menu-wrapper') && !target.closest('.user-dropdown')) {
      this.isUserMenuOpen = false;
    }
    if (!target.closest('.search-modal-content') &&
        !target.closest('.search-button') &&
        !target.closest('.sidebar-search')) {
      this.isSearchOpen = false;
    }
  }

  // Método para navegación (CONSERVADO)
  navigateTo(route: string): void {
    this.router.navigate([route]);
  }

  exportarExcel(): void {
    this.loadingService.show();
    this.denunciaService.exportarEstadisticasExcel().subscribe({
        next: (blob: Blob) => {
            const url = window.URL.createObjectURL(blob);
            const link = document.createElement('a');
            link.href = url;
            link.download = `estadisticas_denuncias_${new Date().toISOString().slice(0, 19).replace(/:/g, '-')}.xlsx`;
            link.click();
            window.URL.revokeObjectURL(url);
            this.loadingService.hide();
            this.notificationService.showSuccess('El archivo Excel se ha generado correctamente');
        },
        error: (error) => {
            this.loadingService.hide();
            console.error('Error exportando a Excel:', error);
            this.notificationService.showError('No se pudo exportar el archivo Excel');
        }
    });
}

exportarPDF(): void {
    this.loadingService.show();
    this.denunciaService.exportarEstadisticasPDF().subscribe({
        next: (blob: Blob) => {
            const url = window.URL.createObjectURL(blob);
            const link = document.createElement('a');
            link.href = url;
            link.download = `estadisticas_denuncias_${new Date().toISOString().slice(0, 19).replace(/:/g, '-')}.pdf`;
            link.click();
            window.URL.revokeObjectURL(url);
            this.loadingService.hide();
            this.notificationService.showSuccess('El archivo PDF se ha generado correctamente');
        },
        error: (error) => {
            this.loadingService.hide();
            console.error('Error exportando a PDF:', error);
            this.notificationService.showError('No se pudo exportar el archivo PDF');
        }
    });
}
}
